// The two authenticator-data checks: the attestation's (once per key, bound
// into the certificate by Apple's nonce) and the assertion's (once per proof,
// signed by the credential key).
//
// Apple's steps, from "Validating apps that connect to your server"
// (developer.apple.com/documentation/devicecheck/validating-apps-that-connect-to-your-server):
//
//   attestation  nonce = SHA256(authData || clientDataHash) equals the 8.2
//                extension; RP ID hash = SHA256(App ID); counter = 0; aaguid
//                is "appattestdevelop" or "appattest" + seven zero bytes.
//   assertion    nonce = SHA256(authenticatorData || SHA256(clientData));
//                the signature is valid for nonce; RP ID hash = SHA256(App ID);
//                counter > previous (> 0 on the first).
//
// "Valid for nonce" means ECDSA-SHA256 over the 32-byte nonce, so the digest
// the curve sees is SHA256(nonce): the Secure Enclave hashes the message it is
// given. takimoto3/app-attest (assertion.go) verifies it that way.
//
// Both authenticator-data blobs are variable length: Apple's page now lists
// CBOR extensions (apple_validation_category_01, apple_bundle_version_01) in
// them. The circuit hashes whatever length is supplied and reads only the
// fixed WebAuthn prefix (rpIdHash 32, flags 1, signCount 4, then for the
// attestation aaguid 16). The extensions are NOT parsed here.

use crate::der::{bytes_at, slice_at};

pub global ATT_AUTH_DATA_MAX_LEN: u32 = 256;
pub global ASSERT_AUTH_DATA_MAX_LEN: u32 = 128;

/// "appattest" followed by seven zero bytes.
global AAGUID_PRODUCTION: [u8; 16] =
    [0x61, 0x70, 0x70, 0x61, 0x74, 0x74, 0x65, 0x73, 0x74, 0, 0, 0, 0, 0, 0, 0];
/// "appattestdevelop".
global AAGUID_DEVELOPMENT: [u8; 16] =
    [0x61, 0x70, 0x70, 0x61, 0x74, 0x74, 0x65, 0x73, 0x74, 0x64, 0x65, 0x76, 0x65, 0x6c, 0x6f, 0x70];

fn be32<let N: u32>(buf: [u8; N], pos: u32) -> u32 {
    ((buf[pos] as u32) << 24)
        | ((buf[pos + 1] as u32) << 16)
        | ((buf[pos + 2] as u32) << 8)
        | (buf[pos + 3] as u32)
}

/// buf[0..len] ++ tail, zero-padded, so a variable-length prefix can be hashed.
fn append_32<let N: u32>(buf: [u8; N], len: u32, tail: [u8; 32]) -> [u8; N + 32] {
    let mut out: [u8; N + 32] = [0; N + 32];
    for i in 0..N {
        if i < len {
            out[i] = buf[i];
        }
    }
    for i in 0..32 {
        out[len + i] = tail[i];
    }
    out
}

fn zero_past<let N: u32>(buf: [u8; N], len: u32) {
    for i in 0..N {
        if i >= len {
            assert(buf[i] == 0, "Authenticator data padding is not zero");
        }
    }
}

/// The attestation's authenticator data is the one Apple certified for this
/// key, is for this app, and comes from the environment the verifier asked for.
pub fn check_attestation_auth_data<let N: u32>(
    auth_data: [u8; N],
    auth_len: u32,
    client_data_hash: [u8; 32],
    cert_nonce: [u8; 32],
    app_id_hash: [u8; 32],
    production: bool,
) {
    // rpIdHash 32 + flags 1 + counter 4 + aaguid 16 + credIdLen 2 + credId 32
    // + COSE key 77 = 164, the shape of the real one.
    assert((auth_len >= 164) & (auth_len <= N), "Attestation authenticator data length out of range");
    zero_past(auth_data, auth_len);
    let nonce = sha256::sha256_var(append_32(auth_data, auth_len, client_data_hash), auth_len + 32);
    assert(nonce == cert_nonce, "Attestation authenticator data is not the one Apple certified");
    assert(bytes_at(auth_data, 0, app_id_hash), "Attestation is not for this app");
    assert(be32(auth_data, 33) == 0, "Attestation counter is not zero");
    let aaguid: [u8; 16] = slice_at(auth_data, 37);
    let want = if production { AAGUID_PRODUCTION } else { AAGUID_DEVELOPMENT };
    assert(aaguid == want, "App Attest environment does not match");
}

/// The digest the credential key signs in an assertion over clientData,
/// SHA256(SHA256(authenticatorData || clientDataHash)), after checking the
/// authenticatorData is for this app with a non-zero counter. Returns
/// (digest, counter). `client_data_hash` is SHA256(clientData).
pub fn assertion_digest<let N: u32>(
    auth_data: [u8; N],
    auth_len: u32,
    client_data_hash: [u8; 32],
    app_id_hash: [u8; 32],
) -> ([u8; 32], u32) {
    assert((auth_len >= 37) & (auth_len <= N), "Assertion authenticator data length out of range");
    zero_past(auth_data, auth_len);
    let nonce = sha256::sha256_var(append_32(auth_data, auth_len, client_data_hash), auth_len + 32);
    assert(bytes_at(auth_data, 0, app_id_hash), "Assertion is not for this app");
    let counter = be32(auth_data, 33);
    assert(counter > 0, "Assertion counter is zero");
    (sha256::digest(nonce), counter)
}

/// The assertion is signed by the credential key over this clientData, for
/// this app. Returns the counter.
pub fn verify_assertion<let N: u32, let C: u32>(
    key_x: [u8; 32],
    key_y: [u8; 32],
    auth_data: [u8; N],
    auth_len: u32,
    client_data: [u8; C],
    signature: [u8; 64],
    app_id_hash: [u8; 32],
) -> u32 {
    let (digest, counter) = assertion_digest(auth_data, auth_len, sha256::digest(client_data), app_id_hash);
    // std's P-256 verification is a Barretenberg black box; it refuses a
    // high s, so the prover supplies the low form (n - s) when Apple's is high.
    assert(
        std::ecdsa_secp256r1::verify_signature(key_x, key_y, signature, digest),
        "Assertion signature is invalid",
    );
    counter
}

221.source:
// The App Attest credential certificate: Apple's statement that a P-256 key
// lives in a device's Secure Enclave and belongs to one app.
//
// WHAT IS CHECKED HERE
//
//   1. The TBS is signed by the App Attest intermediate CA key, ECDSA P-384
//      over SHA-256 of the TBS. (Not SHA-384: Apple's credential certificates
//      carry ecdsa-with-SHA256 -- read from a real one, see tests.nr. Only the
//      root -> intermediate link uses SHA-384; see intermediate.nr.)
//   2. The TBS is walked field by field (bounded DER, no pattern search) to:
//      - the signature algorithm, which must be ecdsa-with-SHA256,
//      - the SubjectPublicKeyInfo, which must be an uncompressed P-256 key,
//      - the extensions, of which exactly one must be Apple's app-identity
//        extension (1.2.840.113635.100.8.5) naming THIS app, and exactly one
//        Apple's nonce extension (1.2.840.113635.100.8.2).
//
// FORMAT ASSUMPTIONS, each from a real certificate (zkPassport's iOS test
// vector, issued 2025-08-26, verified against Apple's published root):
//   - version v3, a serial of 1..20 bytes, issuer/validity/subject in that
//     order, then SPKI, then [3] extensions and nothing after them;
//   - the app id is item [1204] (tag BF 89 34) of the 8.5 extension's
//     SEQUENCE, holding an OCTET STRING of the App ID. Apple does not
//     document this extension; zkPassport reads the same item.
//   - the nonce extension value is SEQUENCE { [1] { OCTET STRING (32) } },
//     which Apple does document ("a DER-encoded ASN.1 sequence ... the single
//     octet string that it contains").
// Positions are never fixed offsets: the serial length and every name length
// are read from the bytes.

use crate::der::{bytes_at, der_element, der_length, slice_at};
use bignum::bignum::BigNum;
use bignum::fields::secp384r1Fq::Secp384r1_Fq;
use bignum::fields::secp384r1Fr::Secp384r1_Fr;
use ecdsa::ecdsa::verify_secp384r1_ecdsa;

/// Room for a credential TBS. The real one measured 852 bytes.
pub global CREDENTIAL_TBS_MAX_LEN: u32 = 1000;

/// At most this many extensions are walked. The real certificate has 5.
global MAX_EXTENSIONS: u32 = 8;
/// At most this many items in the app-identity extension. The real one has 13.
global MAX_APP_ID_ITEMS: u32 = 20;

/// [0] { INTEGER 2 } -- X.509 v3.
global VERSION_V3: [u8; 5] = [0xa0, 0x03, 0x02, 0x01, 0x02];

/// AlgorithmIdentifier ecdsa-with-SHA256 (1.2.840.10045.4.3.2).
global SIG_ALG_ECDSA_SHA256: [u8; 12] =
    [0x30, 0x0a, 0x06, 0x08, 0x2a, 0x86, 0x48, 0xce, 0x3d, 0x04, 0x03, 0x02];

/// SubjectPublicKeyInfo header for id-ecPublicKey / prime256v1, through the
/// BIT STRING's unused-bits byte and the 0x04 uncompressed-point marker.
global SPKI_P256_PREFIX: [u8; 27] = [
    0x30, 0x59, 0x30, 0x13, 0x06, 0x07, 0x2a, 0x86, 0x48, 0xce, 0x3d, 0x02, 0x01, 0x06, 0x08, 0x2a,
    0x86, 0x48, 0xce, 0x3d, 0x03, 0x01, 0x07, 0x03, 0x42, 0x00, 0x04,
];

/// OBJECT IDENTIFIER 1.2.840.113635.100.8 -- Apple's App Attest arc -- with
/// its tag and length; the last arc follows.
global APPLE_ATTEST_OID_PREFIX: [u8; 10] =
    [0x06, 0x09, 0x2a, 0x86, 0x48, 0x86, 0xf7, 0x63, 0x64, 0x08];
global OID_LAST_NONCE: u8 = 0x02;
global OID_LAST_APP_ID: u8 = 0x05;

/// SEQUENCE { [1] { OCTET STRING (32) } }, the nonce extension's value.
global NONCE_VALUE_PREFIX: [u8; 6] = [0x30, 0x24, 0xa1, 0x22, 0x04, 0x20];

/// Tag of the app-identity item inside the 8.5 extension.
global APP_ID_ITEM_TAG: [u8; 3] = [0xbf, 0x89, 0x34];

pub struct CredentialKey {
    pub x: [u8; 32],
    pub y: [u8; 32],
    /// What Apple wrote into extension 1.2.840.113635.100.8.2:
    /// SHA256(attestation authData || attestation clientDataHash).
    pub nonce: [u8; 32],
}

/// The TBS length, from its own header; everything past it must be zero so
/// the array has exactly one meaning.
fn tbs_length<let N: u32>(tbs: [u8; N], tbs_len: u32) {
    assert(tbs_len <= N, "TBS longer than the circuit allows");
    let (hl, cl) = der_element(tbs, 0, 0x30);
    assert(hl + cl == tbs_len, "TBS length does not match its header");
    for i in 0..N {
        if i >= tbs_len {
            assert(tbs[i] == 0, "TBS padding is not zero");
        }
    }
}

/// Walk the app-identity extension's value and require exactly one [1204]
/// item, holding exactly `app_id`.
fn check_app_id<let N: u32, let A: u32>(tbs: [u8; N], start: u32, end: u32, app_id: [u8; A]) {
    let (hl, cl) = der_element(tbs, start, 0x30);
    assert(start + hl + cl == end, "App id extension length mismatch");
    let mut q = start + hl;
    let mut found: u32 = 0;
    for _ in 0..MAX_APP_ID_ITEMS {
        if q < end {
            // Context tags are one byte (A4) or, for numbers >= 31, three
            // (BF 89 34): Apple's items stop below 2^14. Anything else is
            // refused rather than skipped by a guess.
            let first = tbs[q];
            let mut tag_len: u32 = 1;
            if (first & 0x1f) == 0x1f {
                assert((tbs[q + 1] & 0x80) != 0, "Unsupported DER tag form");
                assert((tbs[q + 2] & 0x80) == 0, "Unsupported DER tag form");
                tag_len = 3;
            }
            let (fl, item_len) = der_length(tbs, q + tag_len);
            let content = q + tag_len + fl;
            if (tag_len == 3) & bytes_at(tbs, q, APP_ID_ITEM_TAG) {
                assert(item_len == 2 + A, "Credential certificate is for another app");
                assert(tbs[content] == 0x04, "App id item is not an OCTET STRING");
                assert(tbs[content + 1] as u32 == A, "Credential certificate is for another app");
                assert(bytes_at(tbs, content + 2, app_id), "Credential certificate is for another app");
                found += 1;
            }
            q = content + item_len;
        }
    }
    assert(q == end, "App id extension has more items than the circuit walks");
    assert(found == 1, "Credential certificate is for another app");
}

/// Walk the TBS and return the credential key and Apple's nonce, refusing
/// anything that is not shaped as an App Attest credential certificate for
/// `app_id`.
pub fn parse_credential_tbs<let N: u32, let A: u32>(
    tbs: [u8; N],
    tbs_len: u32,
    app_id: [u8; A],
) -> CredentialKey {
    tbs_length(tbs, tbs_len);
    let (outer_hl, _) = der_element(tbs, 0, 0x30);
    let mut pos = outer_hl;

    assert(bytes_at(tbs, pos, VERSION_V3), "Certificate is not X.509 v3");
    pos += 5;

    let (shl, scl) = der_element(tbs, pos, 0x02);
    assert((scl >= 1) & (scl <= 20), "Certificate serial length out of range");
    pos += shl + scl;

    assert(bytes_at(tbs, pos, SIG_ALG_ECDSA_SHA256), "Certificate is not signed with ecdsa-with-SHA256");
    pos += 12;

    // issuer, validity, subject: skipped by their own lengths. The issuer is
    // not compared -- the CA key's signature is what binds it.
    for _ in 0..3 {
        let (hl, cl) = der_element(tbs, pos, 0x30);
        pos += hl + cl;
    }

    assert(bytes_at(tbs, pos, SPKI_P256_PREFIX), "Credential key is not an uncompressed P-256 key");
    let x: [u8; 32] = slice_at(tbs, pos + 27);
    let y: [u8; 32] = slice_at(tbs, pos + 59);
    pos += 91;

    // [3] { SEQUENCE OF Extension }, ending exactly at the end of the TBS.
    let (ehl, ecl) = der_element(tbs, pos, 0xa3);
    let ext_end = pos + ehl + ecl;
    assert(ext_end == tbs_len, "Extensions are not the last TBS field");
    pos += ehl;
    let (shl2, scl2) = der_element(tbs, pos, 0x30);
    assert(pos + shl2 + scl2 == ext_end, "Extension list length mismatch");
    pos += shl2;

    let mut nonce_count: u32 = 0;
    let mut app_id_count: u32 = 0;
    let mut nonce_pos: u32 = 0;
    let mut nonce_len: u32 = 0;
    let mut app_id_start: u32 = 0;
    let mut app_id_end: u32 = 0;

    for _ in 0..MAX_EXTENSIONS {
        if pos < ext_end {
            // Extension ::= SEQUENCE { OID, critical BOOLEAN OPTIONAL, OCTET STRING }
            let (hl, cl) = der_element(tbs, pos, 0x30);
            let ext_next = pos + hl + cl;
            let oid_pos = pos + hl;
            let (ohl, ocl) = der_element(tbs, oid_pos, 0x06);
            let is_apple = bytes_at(tbs, oid_pos, APPLE_ATTEST_OID_PREFIX);
            let last = tbs[oid_pos + 10];
            let mut v = oid_pos + ohl + ocl;
            if tbs[v] == 0x01 {
                let (bhl, bcl) = der_element(tbs, v, 0x01);
                v += bhl + bcl;
            }
            let (vhl, vcl) = der_element(tbs, v, 0x04);
            assert(v + vhl + vcl == ext_next, "Extension length mismatch");
            if is_apple & (last == OID_LAST_NONCE) {
                nonce_count += 1;
                nonce_pos = v + vhl;
                nonce_len = vcl;
            }
            if is_apple & (last == OID_LAST_APP_ID) {
                app_id_count += 1;
                app_id_start = v + vhl;
                app_id_end = v + vhl + vcl;
            }
            pos = ext_next;
        }
    }
    assert(pos == ext_end, "Certificate has more extensions than the circuit walks");

    assert(nonce_count == 1, "Credential certificate has no single nonce extension");
    assert(nonce_len == 38, "Nonce extension is not one 32-byte OCTET STRING");
    assert(bytes_at(tbs, nonce_pos, NONCE_VALUE_PREFIX), "Nonce extension is not one 32-byte OCTET STRING");
    let nonce: [u8; 32] = slice_at(tbs, nonce_pos + 6);

    assert(app_id_count == 1, "Credential certificate is for another app");
    check_app_id(tbs, app_id_start, app_id_end, app_id);

    CredentialKey { x, y, nonce }
}

/// ECDSA P-384 over SHA-256 of the TBS, by the CA key. `sig_s` must be the
/// low form (s <= n/2): the library refuses the other, and the prover
/// replaces Apple's s with n - s when needed -- the same signature.
pub fn verify_credential_signature<let N: u32>(
    ca_x: [u8; 48],
    ca_y: [u8; 48],
    tbs: [u8; N],
    tbs_len: u32,
    sig_r: [u8; 48],
    sig_s: [u8; 48],
) -> bool {
    let digest = sha256::sha256_var(tbs, tbs_len);
    let px: Secp384r1_Fq = Secp384r1_Fq::from_be_bytes(ca_x);
    let py: Secp384r1_Fq = Secp384r1_Fq::from_be_bytes(ca_y);
    let r: Secp384r1_Fr = Secp384r1_Fr::from_be_bytes(sig_r);
    let s: Secp384r1_Fr = Secp384r1_Fr::from_be_bytes(sig_s);
    verify_secp384r1_ecdsa(px, py, digest, (r, s))
}

222.source:
// Bounded DER reading at witness-chosen positions.
//
// Every read here is at an offset the prover supplies indirectly (through the
// bytes of a certificate), so every function asserts what it relies on rather
// than trusting the shape. Only the length forms an App Attest credential
// certificate uses are accepted: short form, 0x81 and 0x82. A longer form is
// refused, never misread.

/// Length field starting at `pos`: (bytes the length field occupies, content length).
pub fn der_length<let N: u32>(buf: [u8; N], pos: u32) -> (u32, u32) {
    let b = buf[pos];
    let mut field_len: u32 = 1;
    let mut content_len: u32 = b as u32;
    if b == 0x81 {
        field_len = 2;
        content_len = buf[pos + 1] as u32;
        assert(content_len >= 0x80, "DER length is not minimal");
    } else if b == 0x82 {
        field_len = 3;
        content_len = (buf[pos + 1] as u32) * 256 + (buf[pos + 2] as u32);
        assert(content_len >= 0x100, "DER length is not minimal");
    } else {
        assert(b < 0x80, "Unsupported DER length form");
    }
    (field_len, content_len)
}

/// A one-byte-tag element at `pos`: (header length, content length), with the
/// tag checked.
pub fn der_element<let N: u32>(buf: [u8; N], pos: u32, tag: u8) -> (u32, u32) {
    assert(buf[pos] == tag, "Unexpected DER tag");
    let (field_len, content_len) = der_length(buf, pos + 1);
    (1 + field_len, content_len)
}

/// True when `want` sits at `pos`.
pub fn bytes_at<let N: u32, let M: u32>(buf: [u8; N], pos: u32, want: [u8; M]) -> bool {
    let mut same = true;
    for i in 0..M {
        same &= buf[pos + i] == want[i];
    }
    same
}

/// M bytes from `pos`.
pub fn slice_at<let N: u32, let M: u32>(buf: [u8; N], pos: u32) -> [u8; M] {
    let mut out: [u8; M] = [0; M];
    for i in 0..M {
        out[i] = buf[pos + i];
    }
    out
}

#[test]
fn short_and_long_lengths() {
    let buf: [u8; 8] = [0x30, 0x05, 0x30, 0x81, 0x90, 0x30, 0x82, 0x01];
    assert(der_length(buf, 1) == (1, 5));
    assert(der_length(buf, 3) == (2, 0x90));
}

#[test(should_fail_with = "DER length is not minimal")]
fn a_long_form_short_length_is_refused() {
    let buf: [u8; 3] = [0x30, 0x81, 0x05];
    let _ = der_length(buf, 1);
}

#[test(should_fail_with = "Unsupported DER length form")]
fn a_three_byte_length_is_refused() {
    let buf: [u8; 6] = [0x30, 0x83, 0x01, 0x00, 0x00, 0x00];
    let _ = der_length(buf, 1);
}

224.source:
// Apple App Attest, verified in a circuit: "a genuine instance of this app,
// on a genuine Apple device, signed this clientData".
//
// The chain is Apple root -> App Attest intermediate CA -> credential
// certificate (one per app key) -> assertion (one per request). Two entry
// points:
//   app_attest_signing_key           the caller pins Apple's ROOT key and the
//                                    intermediate is verified here (SHA-384,
//                                    P-384, cA = TRUE) -- what zkPassport does;
//   app_attest_signing_key_under_ca  the caller pins the INTERMEDIATE's key
//                                    and everything from the credential
//                                    certificate down is verified here.
// coinbase_attestation_v2 uses the second (decided 2026-10-27,
// .claude/agents/circuits-dev.md): the root link costs it 669,935 gates and
// a 2^21 circuit; pinning "Apple App Attestation CA 1" keeps it at 2^20, at
// the price of a circuit release when Apple replaces that intermediate
// (valid to 2030-03-13). The first stays, with its tests on Apple's real
// root -> CA 1 chain, because it is how that intermediate key was checked.

pub mod der;
pub mod intermediate;
pub mod credential;
pub mod assertion;
mod tests;

use intermediate::{parse_intermediate_tbs, verify_intermediate_signature};
use credential::{parse_credential_tbs, verify_credential_signature};
use assertion::{assertion_digest, check_attestation_auth_data};

pub use intermediate::INTERMEDIATE_TBS_MAX_LEN;
pub use credential::CREDENTIAL_TBS_MAX_LEN;
pub use assertion::{ASSERT_AUTH_DATA_MAX_LEN, ATT_AUTH_DATA_MAX_LEN};

/// Everything a device contributes to one App Attest statement, except the
/// assertion signature itself (the caller verifies that, so one P-256 check
/// can serve more than one kind of signer).
pub struct AppAttestChain<let ITBS: u32, let TBS: u32, let ATT: u32, let ASSERT: u32> {
    /// The intermediate CA certificate's TBS (zero-padded) and the root's
    /// signature over it, r || s, s in low form.
    pub intermediate_tbs: [u8; ITBS],
    pub intermediate_tbs_len: u32,
    pub intermediate_sig: [u8; 96],
    /// The credential certificate's TBS (zero-padded) and the intermediate's
    /// signature over it, r || s, s in low form.
    pub credential_tbs: [u8; TBS],
    pub credential_tbs_len: u32,
    pub credential_sig: [u8; 96],
    /// The attestation object's authData and the clientDataHash it was made
    /// with (SHA256 of the attestation challenge). Kept by the app.
    pub att_auth_data: [u8; ATT],
    pub att_auth_data_len: u32,
    pub att_client_data_hash: [u8; 32],
    /// The assertion's authenticatorData (zero-padded).
    pub assertion_auth_data: [u8; ASSERT],
    pub assertion_auth_data_len: u32,
}

/// AppAttestChain without the intermediate: what a device contributes when
/// the caller pins the intermediate CA's key.
pub struct CredentialChain<let TBS: u32, let ATT: u32, let ASSERT: u32> {
    pub credential_tbs: [u8; TBS],
    pub credential_tbs_len: u32,
    pub credential_sig: [u8; 96],
    pub att_auth_data: [u8; ATT],
    pub att_auth_data_len: u32,
    pub att_client_data_hash: [u8; 32],
    pub assertion_auth_data: [u8; ASSERT],
    pub assertion_auth_data_len: u32,
}

/// The credential key, the digest it must have signed for `client_data_hash`,
/// and the assertion counter, under a PINNED intermediate CA key (P-384,
/// X and Y). Asserts:
///   ca --SHA-256/P-384--> credential certificate (our App ID, P-256 key,
///                         Apple's nonce)
///   attestation authData hashes to that nonce, is for our app, counter 0,
///   AAGUID of the requested environment
///   assertion authData is for our app, counter > 0
pub fn app_attest_signing_key_under_ca<let TBS: u32, let ATT: u32, let ASSERT: u32, let A: u32>(
    chain: CredentialChain<TBS, ATT, ASSERT>,
    ca_x: [u8; 48],
    ca_y: [u8; 48],
    app_id: [u8; A],
    app_id_hash: [u8; 32],
    production: bool,
    client_data_hash: [u8; 32],
) -> ([u8; 32], [u8; 32], [u8; 32], u32) {
    // A caller that branches (coinbase-attestation-v2's server kind passes
    // zeros here) gets a named refusal instead of the first library assert
    // the zeros happen to trip.
    assert(chain.credential_tbs_len != 0, "No App Attest certificate chain");
    let mut r: [u8; 48] = [0; 48];
    let mut s: [u8; 48] = [0; 48];
    for i in 0..48 {
        r[i] = chain.credential_sig[i];
        s[i] = chain.credential_sig[48 + i];
    }
    assert(
        verify_credential_signature(
            ca_x,
            ca_y,
            chain.credential_tbs,
            chain.credential_tbs_len,
            r,
            s,
        ),
        "Credential certificate is not signed by the App Attest intermediate",
    );

    let key = parse_credential_tbs(chain.credential_tbs, chain.credential_tbs_len, app_id);

    check_attestation_auth_data(
        chain.att_auth_data,
        chain.att_auth_data_len,
        chain.att_client_data_hash,
        key.nonce,
        app_id_hash,
        production,
    );

    let (digest, counter) = assertion_digest(
        chain.assertion_auth_data,
        chain.assertion_auth_data_len,
        client_data_hash,
        app_id_hash,
    );
    (key.x, key.y, digest, counter)
}

/// The credential key, the digest it must have signed for `client_data_hash`,
/// and the assertion counter. Asserts every link from `root` down:
///   root --SHA-384/P-384--> intermediate (a CA, P-384 key)
///        --SHA-256/P-384--> credential certificate (our App ID, P-256 key,
///                           Apple's nonce)
///   attestation authData hashes to that nonce, is for our app, counter 0,
///   AAGUID of the requested environment
///   assertion authData is for our app, counter > 0
pub fn app_attest_signing_key<let ITBS: u32, let TBS: u32, let ATT: u32, let ASSERT: u32, let A: u32>(
    chain: AppAttestChain<ITBS, TBS, ATT, ASSERT>,
    root_x: [u8; 48],
    root_y: [u8; 48],
    app_id: [u8; A],
    app_id_hash: [u8; 32],
    production: bool,
    client_data_hash: [u8; 32],
) -> ([u8; 32], [u8; 32], [u8; 32], u32) {
    // A caller that branches (coinbase-attestation-v2's server kind passes
    // zeros here) gets a named refusal instead of the first library assert
    // the zeros happen to trip.
    assert(chain.intermediate_tbs_len != 0, "No App Attest intermediate certificate");
    let mut r: [u8; 48] = [0; 48];
    let mut s: [u8; 48] = [0; 48];
    for i in 0..48 {
        r[i] = chain.intermediate_sig[i];
        s[i] = chain.intermediate_sig[48 + i];
    }
    assert(
        verify_intermediate_signature(
            root_x,
            root_y,
            chain.intermediate_tbs,
            chain.intermediate_tbs_len,
            r,
            s,
        ),
        "Intermediate is not signed by Apple's App Attestation root",
    );
    let ca = parse_intermediate_tbs(chain.intermediate_tbs, chain.intermediate_tbs_len);

    app_attest_signing_key_under_ca(
        CredentialChain {
            credential_tbs: chain.credential_tbs,
            credential_tbs_len: chain.credential_tbs_len,
            credential_sig: chain.credential_sig,
            att_auth_data: chain.att_auth_data,
            att_auth_data_len: chain.att_auth_data_len,
            att_client_data_hash: chain.att_client_data_hash,
            assertion_auth_data: chain.assertion_auth_data,
            assertion_auth_data_len: chain.assertion_auth_data_len,
        },
        ca.x,
        ca.y,
        app_id,
        app_id_hash,
        production,
        client_data_hash,
    )
}

